item.aggregated_output:
    for value in command:
        if SECRET_OPTION.match(value) or SECRET_URI.match(value) or SECRET_ASSIGNMENT.search(value):
            raise GateError("command argv contains a secret-bearing option or credential URI")


def command_cwd(project: Path, value: str) -> tuple[Path, str]:
    candidate = Path(value).expanduser()
    path = (candidate if candidate.is_absolute() else project / candidate).resolve(strict=True)
    if project != path and project not in path.parents:
        raise GateError("command cwd must remain inside the project")
    if path.is_symlink() or not path.is_dir():
        raise GateError("command cwd must be a real project directory")
    return path, path.relative_to(project).as_posix() if path != project else "."


def parse_expected_json(stdout: bytes) -> dict:
    if len(stdout) > MAX_EXPECTED_JSON_BYTES:
        raise GateError("expected JSON stdout exceeds the bounded validation limit")
    try:
        document = json.loads(stdout.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise GateError("command stdout is not one valid JSON document") from error
    if not isinstance(document, dict):
        raise GateError("command stdout JSON must be an object")
    return document


def bounded_diagnostic_string(value, field: str, maximum: int, *, required: bool = False) -> str | None:
    if value is None and not required:
        return None
    if not isinstance(value, str) or (required and not value) or len(value) > maximum:
        raise GateError(f"project check diagnostic {field} is invalid or exceeds its bound")
    if any(ord(character) < 32 and character != "\t" for character in value):
        raise GateError(f"project check diagnostic {field} contains control characters")
    return value


def sanitize_diagnostic_message(value: str) -> tuple[str, bool]:
    sanitized = SENSITIVE_DIAGNOSTIC_ASSIGNMENT.sub(lambda match: f"{match.group(1)}=<redacted>", value)
    sanitized = SENSITIVE_DIAGNOSTIC_URI.sub(lambda match: f"{match.group(1)}<redacted>@", sanitized)
    sanitized = SENSITIVE_DIAGNOSTIC_BEARER.sub("Bearer <redacted>", sanitized)
    return sanitized, sanitized != value


def project_check_diagnostic(value) -> tuple[dict, bool]:
    if not isinstance(value, dict):
        raise GateError("project check diagnostic inventory has an invalid row")
    allowed_fields = {
        "code", "message", "path", "line", "column", "symbol",
        "action", "event", "variable", "owner", "category",
    }
    if any(key not in allowed_fields for key in value):
        raise GateError("project check diagnostic inventory has an unknown field")
    code = bounded_diagnostic_string(value.get("code"), "code", 200, required=True)
    if not DIAGNOSTIC_CODE.fullmatch(code):
        raise GateError("project check diagnostic code is invalid")
    message = bounded_diagnostic_string(
        value.get("message"), "message", MAX_DIAGNOSTIC_MESSAGE_CHARS, required=True,
    )
    message, redacted = sanitize_diagnostic_message(message)
    row = {"code": code, "message": message}
    for field in ("symbol", "action", "event", "variable", "owner", "category"):
        item = bounded_diagnostic_string(
            value.get(field), field, MAX_DIAGNOSTIC_IDENTITY_CHARS,
            required=field in {"owner", "category"},
        )
        if item is not None:
            item, item_redacted = sanitize_diagnostic_message(item)
            row[field] = item
            redacted = redacted or item_redacted
    path = bounded_diagnostic_string(value.get("path"), "path", MAX_DIAGNOSTIC_PATH_CHARS)
    if path is not None:
        path, path_redacted = sanitize_diagnostic_message(path)
        redacted = redacted or path_redacted
        normalized = Path(path)
        if normalized.is_absolute() or ".." in normalized.parts or "\\" in path:
            raise GateError("project check diagnostic path must be project-relative")
        row["path"] = path
    for field in ("line", "column"):
        item = value.get(field)
        if item is not None:
            if isinstance(item, bool) or not isinstance(item, int) or item <= 0 or item > 10_000_000:
                raise GateError(f"project check diagnostic {field} is invalid")
            row[field] = item
    if row["category"] != "actions":
        raise GateError("project check diagnostic category is not actions")
    return row, redacted


def project_check_proof(stdout: bytes, project: Path) -> dict:
    document = parse_expected_json(stdout)
    allowed_fields = {
        "contract_version", "state", "project_root", "scope",
        "summary", "issue_count", "diagnostics",
    }
    if set(document) != allowed_fields:
        raise GateError("project check JSON document does not match the supported schema")
    if document.get("contract_version") not in SUPPORTED_PROJECT_CHECK_CONTRACTS:
        raise GateError("command JSON contract is not a supported project-check contract")
    if document.get("state") not in {"valid", "invalid", "repair_required"}:
        raise GateError("project check JSON state is invalid")
    if document.get("scope") != "actions":
        raise GateError("project check JSON scope is not actions")
    project_root = bounded_diagnostic_string(
        document.get("project_root"), "project_root", MAX_DIAGNOSTIC_PATH_CHARS, required=True,
    )
    if Path(project_root).expanduser().resolve() != project:
        raise GateError("project check JSON project root did not match the Gate project")
    bounded_diagnostic_string(
        document.get("summary"), "summary", MAX_DIAGNOSTIC_MESSAGE_CHARS, required=True,
    )
    issue_count = document.get("issue_count")
    if isinstance(issue_count, bool) or not isinstance(issue_count, int) or issue_count < 0:
        raise GateError("project check issue count is invalid")
    diagnostics = document.get("diagnostics")
    if diagnostics is None and document.get("state") == "valid" and issue_count == 0:
        diagnostics = []
    if not isinstance(diagnostics, list) or len(diagnostics) > MAX_DIAGNOSTICS or issue_count != len(diagnostics):
        raise GateError("project check diagnostic inventory is inconsistent or exceeds its bound")
    bounded = []
    redacted = False
    for value in diagnostics:
        row, row_redacted = project_check_diagnostic(value)
        bounded.append(row)
        redacted = redacted or row_redacted
    if document["state"] == "valid" and issue_count != 0:
        raise GateError("valid project check must have an empty diagnostic inventory")
    if document["state"] != "valid" and not diagnostics:
        raise GateError("failed project check must have a diagnostic inventory")
    return {
        "contract_version": document["contract_version"],
        "state": document["state"],
        "scope": document["scope"],
        "issue_count": issue_count,
        "diagnostics": bounded,
        "diagnostics_redacted": redacted,
        "diagnostics_sha256": sha256_bytes(json.dumps(diagnostics, sort_keys=True, separators=(",", ":")).encode("utf-8")),
    }


def validate_project_check_expectation(proof: dict, args) -> None:
    if proof["contract_version"] != args.expect_json_contract:
        raise GateError("command JSON contract did not match expectation")
    if proof["state"] != args.expect_json_state:
        raise GateError("command JSON state did not match expectation")
    expected_codes = sorted(set(args.expect_json_diagnostic_code))
    actual_codes = sorted({value["code"] for value in proof["diagnostics"]})
    if args.expect_json_state == "valid":
        if proof["issue_count"] != 0 or expected_codes:
            raise GateError("valid project check must have an empty diagnostic inventory")
    elif not expected_codes or actual_codes != expected_codes:
        raise GateError("invalid project check diagnostic codes did not match expectation")


def delivery_string(document: dict, key: str, maximum: int = 1024) -> str:
    value = document.get(key)
    if not isinstance(value, str) or not value or len(value) > maximum:
        raise GateError(f"project delivery JSON {key} is invalid or exceeds its bound")
    if any(ord(character) < 32 for character in value):
        raise GateError(f"project delivery JSON {key} contains control characters")
    return value


def delivery_sha(document: dict, key: str) -> str:
    value = delivery_string(document, key, 64)
    if not re.fullmatch(r"[0-9a-f]{64}", value):
        raise GateError(f"project delivery JSON {key} is not a SHA-256")
    return value


def bounded_project_json(project: Path, relative: str) -> tuple[dict, dict]:
    item = evidence_item(project, relative)
    if item["bytes"] > MAX_EXPECTED_JSON_BYTES:
        raise GateError("project delivery receipt exceeds the bounded validation limit")
    path = project / relative
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise GateError("project delivery receipt is not valid JSON") from error
    if not isinstance(document, dict):
        raise GateError("project delivery receipt must be a JSON object")
    return document, item


def project_verification_proof(stdout: bytes, project: Path) -> dict:
    result = parse_expected_json(stdout)
    if set(result) != {
        "contract_version", "delivery_id", "receipt_path", "receipt_sha256",
        "generated_tree_sha256", "project_source_tree_sha256", "user_source_sha256",
    }:
        raise GateError("project verify JSON document does not match the supported response schema")
    if result.get("contract_version") != PROJECT_VERIFICATION_CONTRACT:
        raise GateError("project verify JSON contract did not match the actual response contract")
    if delivery_string(result, "receipt_path") != VERIFICATION_RECEIPT:
        raise GateError("project verify JSON receipt path is invalid")
    delivery_string(result, "delivery_id", 512)
    for key in ("receipt_sha256", "generated_tree_sha256", "project_source_tree_sha256", "user_source_sha256"):
        delivery_sha(result, key)
    receipt, artifact = bounded_project_json(project, VERIFICATION_RECEIPT)
    if receipt.get("contract_version") != PROJECT_VERIFICATION_CONTRACT:
        raise GateError("project verification receipt contract differs")
    if delivery_sha(receipt, "receipt_sha256") != result["receipt_sha256"]:
        raise GateError("project verification response and receipt identities differ")
    runtime_manifest_sha = delivery_sha(receipt, "runtime_manifest_sha256")
    if runtime_manifest_sha != delivery_runtime_manifest_sha(project):
        raise GateError("project verification receipt runtime manifest identity is stale")
    checks = receipt.get("checks")
    if not isinstance(checks, list) or not checks or len(checks) > 100:
        raise GateError("project verification receipt check inventory is invalid or exceeds its bound")
    names = []
    for check in checks:
        if not isinstance(check, dict) or any(key not in {"name", "status", "argv", "depends_on", "failure"} for key in check):
            raise GateError("project verification receipt has an invalid check row")
        name = delivery_string(check, "name", 256)
        if name in names or check.get("status") != "passed":
            raise GateError("project verification receipt is not one complete passing check inventory")
        names.append(name)
    return {
        **artifact,
        "contract_version": PROJECT_VERIFICATION_CONTRACT,
        "state": "passed",
        "receipt_sha256": result["receipt_sha256"],
        "runtime_manifest_sha256": runtime_manifest_sha,
        "check_count": len(checks),
        "passed_check_count": len(checks),
        "checks_sha256": sha256_bytes(json.dumps(checks, sort_keys=True, separators=(",", ":")).encode("utf-8")),
    }


