def option_value(command: list[str], name: str) -> str:
    for index, value in enumerate(command):
        if value == name and index + 1 < len(command):
            return command[index + 1]
        if value.startswith(name + "="):
            return value.split("=", 1)[1]
    return ""


def domainry_command(command: list[str], family: tuple[str, ...], project: Path) -> bool:
    if len(command) < len(family) + 1 or Path(command[0]).name not in {"domainry-cli", "domainry-cli.exe"}:
        return False
    if tuple(command[1:1 + len(family)]) != family or "--json" not in command:
        return False
    raw_project = option_value(command, "--project")
    if not raw_project:
        return False
    try:
        return Path(raw_project).expanduser().resolve() == project
    except OSError:
        return False


def command_kind(label: str, command: list[str], project: Path) -> str:
    lowered = label.lower()
    verifies_project = "project verification" in lowered or "project verify" in lowered
    packages_project = "project packaging" in lowered or "packaging pass" in lowered or "project package" in lowered
    if verifies_project and packages_project:
        raise GateError("project verification and packaging must be separate Gates")
    if verifies_project:
        if not domainry_command(command, ("project", "verify"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_verify"
    if packages_project:
        if not domainry_command(command, ("project", "package"), project):
            raise GateError(f"command does not prove Gate '{label}'")
        return "project_package"
    if "project check" in lowered:
        if not domainry_command(command, ("project", "check"), project) or option_value(command, "--scope") != "actions":
            raise GateError(f"command does not prove Gate '{label}'")
