def validate_command_for_gate(label: str, command: list[str], project: Path) -> str:
    kind = command_kind(label, command, project)
    if kind != "generic":
        return kind
    lowered = " ".join(command).lower()
    label_value = f" {label.lower()} "
    allowed: list[str] = []
    for category_token, category_commands in COMMAND_CATEGORIES:
        if category_token in label_value:
            allowed.extend(category_commands)
    if "focused tests" in label_value or " tests pass" in label_value or "full tests" in label_value:
        executable = Path(command[0]).name.lower()
        go_test = executable in {"go", "go.exe"} and (
            len(command) >= 2 and command[1] == "test"
        )
        javascript_test = (
            executable in {"npm", "npm.exe", "pnpm", "pnpm.exe", "yarn", "yarn.exe"}
            and len(command) >= 2
            and (
                command[1] == "test"
                or len(command) >= 3 and command[1:3] == ["run", "test"]
            )
        ) or executable in {"vitest", "vitest.exe", "jest", "jest.exe"}
        if not go_test and not javascript_test:
            raise GateError(f"command does not prove Gate '{label}'")
        return kind
    if allowed and not any(token in lowered for token in allowed):
        raise GateError(f"command does not prove Gate '{label}'")
    return kind


